/* Reference-led app views. They all read the same fictional model. */
(function(root){
  const U=root.PhoneBridgerUI,{esc,icon,logo,brandNames,button:B,ib,avatar,image,search,nav,toolbar,pill}=U;
  const attrs=(key,id)=>`data-${key}="${esc(id)}"`;
  const empty=text=>`<div class="sim-empty">${icon('folder')}<p>${esc(text)}</p></div>`;
  const top=(app,title,query='',extras='')=>`<header class="sim-search-header">${ib('drawer','Open menu','menu')}${search(title,query)}${extras}${B('profile','J','','aria-label="Demo account"','sim-profile')}</header>`;
  const fileIcon=f=>f.type==='image'?image(f.photo,'sim-file-thumb',f.name):logo(f.type==='sheet'?'sheets':f.type==='video'?'youtube':f.type==='pdf'||f.type==='text'?'docs':'files');
  const attachment=(m,id)=>{const f=m.file(id);if(!f)return '';if(f.voice)return `<div class="sim-voice-note">${ib('voice-play','Play voice note','play')}<span>▂▅▃▆▂▇▃▅▃▂ · Voice note</span><audio preload="none" src="${f.src}"></audio></div>`;return `<div class="sim-attachment">${B('preview',f.name,'',`data-id="${id}"`)}${f.type==='image'?image(id,'',f.name):logo(f.type==='sheet'?'sheets':'docs')}</div>`;};
  function home({m,key}){
    const d=m.data;return `<div class="sim-home-wallpaper"><div class="sim-home-time"><strong>${m.clock}</strong><span>Monday, October 5</span><small>18° · Partly sunny</small></div>${B('launch','Search your apps','search','data-app="google"','sim-home-search')}<div class="sim-home-grid">${Object.entries(brandNames).map(([id,name])=>`<button type="button" data-sim-action="launch" data-app="${id}">${logo(id)}<span>${name}</span>${id==='gmail'||id==='whatsapp'?`<i class="sim-badge" ${!(id==='gmail'?d.mail.filter(x=>x.folder==='inbox'&&!x.read).length:d.threads.reduce((n,t)=>n+t.unread,0))?'hidden':''}>${id==='gmail'?d.mail.filter(x=>x.folder==='inbox'&&!x.read).length:d.threads.reduce((n,t)=>n+t.unread,0)}</i>`:''}</button>`).join('')}</div><div class="sim-home-dock">${['contacts','whatsapp','chrome','phonebridger'].map(id=>B('launch','', '',`data-app="${id}" aria-label="Open ${brandNames[id]}"`).replace('</button>',`${logo(id)}</button>`)).join('')}</div><div class="sim-home-device">${key==='left'?'Left phone':'Right phone'} · Demo</div></div>`;
  }
  function whatsapp({m,u}){
    const d=m.data;
    if(u.thread){const t=d.threads.find(t=>t.id===u.thread);if(!t)return empty('Conversation not found.');m.readThread(t.id);const c=m.contact(t.members.find(x=>x!=='jamie')),messages=d.messages.filter(x=>x.thread===t.id&&!x.deleted);return `<header class="sim-chat-header">${ib('back','Back to chats','back')}${t.group?`<span class="sim-avatar sim-group-avatar">${icon('people')}</span>`:avatar(c)}<button class="sim-chat-heading" data-sim-action="contact-info" data-id="${t.id}"><strong>${esc(t.name)}</strong><small>${t.typing?'typing…':t.group?t.members.map(id=>id==='jamie'?'You':m.contact(id)?.name).join(', '):'Online'}</small></button>${ib('call','Demo video call','video',attrs('id',t.id))}${ib('chat-menu','Chat options','more',attrs('id',t.id))}</header><div class="sim-chat-wallpaper sim-scroll" data-scroll="messages"><div class="sim-chat-day">Today</div>${messages.map(msg=>`<div class="sim-chat-line ${msg.from==='jamie'?'outgoing':'incoming'}"><div class="sim-bubble">${t.group&&msg.from!=='jamie'?`<strong class="sim-sender">${esc(m.contact(msg.from)?.name)}</strong>`:''}${msg.replyTo?`<div class="sim-reply-preview">Reply · ${esc(d.messages.find(x=>x.id===msg.replyTo)?.text.slice(0,65))}</div>`:''}${msg.attachment?attachment(m,msg.attachment):''}${msg.text?`<p>${esc(msg.text)}</p>`:''}<div class="sim-bubble-bottom"><small>${msg.at} ${msg.from==='jamie'?`<span class="sim-ticks ${msg.status}">${msg.status==='sending'?'◷':msg.status==='delivered'?'✓✓':'✓✓'}</span>`:''}</small>${ib('message-menu','Message options','more',attrs('id',msg.id))}</div>${msg.reactions?.length?`<div class="sim-reactions">${msg.reactions.join(' ')}</div>`:''}</div></div>`).join('')}${t.typing?'<div class="sim-typing">typing <span>● ● ●</span></div>':''}</div>${u.replyTo?`<div class="sim-reply-banner">Reply to ${esc(d.messages.find(x=>x.id===u.replyTo)?.text.slice(0,55))}${ib('clear-reply','Cancel reply','close')}</div>`:''}${u.attachment?`<div class="sim-reply-banner">${esc(m.file(u.attachment)?.name)}${ib('clear-attachment','Remove attachment','close')}</div>`:''}<form class="sim-chat-form" data-sim-form="chat">${ib('emoji','Choose emoji','emoji')}<input aria-label="Message to ${esc(t.name)}" placeholder="Message" data-sim-input="chat-text" value="${esc(u.text||'')}" maxlength="2000" autocomplete="off">${ib('attach','Attach a file','attach')}${ib('photo-picker','Choose a photo','camera')}<button type="submit" class="sim-chat-send" aria-label="Send message">${icon('send')}</button>${ib('voice-note','Send a demo voice note','mic')}</form>`;}
    if(u.tab==='Updates')return toolbar('Updates',ib('new-chat','New chat','plus'))+`<div class="sim-scroll sim-status-list"><h3>Status updates</h3>${d.contacts.slice(0,6).map((c,i)=>B('status',c.name,'',attrs('id',c.id),'sim-contact').replace('</button>',`${avatar(c)}${image(d.photos[i].id,'sim-status-photo',d.photos[i].name)}</button>`)).join('')}</div>`+nav([['Chats','mail'],['Updates','clock'],['Communities','people'],['Calls','call']],u.tab);
    if(u.tab==='Calls')return toolbar('Calls',ib('new-chat','New call','plus'))+`<div class="sim-scroll">${d.contacts.slice(0,5).map((c,i)=>`<div class="sim-contact-row">${avatar(c)}<div><strong>${c.name}</strong><small>${i%2?'Outgoing':'Incoming'} · Today, 10:0${i}</small></div>${ib('call',`Call ${c.name}`,'call',attrs('id',c.id))}</div>`).join('')}</div>`+nav([['Chats','mail'],['Updates','clock'],['Communities','people'],['Calls','call']],u.tab);
    const list=d.threads.filter(t=>u.tab==='Communities'?t.group:u.filter==='Archived'?t.archived:!t.archived).filter(t=>u.filter==='Unread'?t.unread>0:u.filter==='Favorites'?t.favorite:u.filter==='Groups'?t.group:true).filter(t=>!u.query||t.name.toLowerCase().includes(u.query.toLowerCase())||d.messages.some(x=>x.thread===t.id&&x.text.toLowerCase().includes(u.query.toLowerCase())));
    return toolbar(u.tab==='Communities'?'Communities':'WhatsApp',ib('photo-picker','Choose photo','camera')+ib('chat-menu','WhatsApp options','more'))+search('Ask Meta AI or Search',u.query)+`<div class="sim-pills">${['All','Unread','Favorites','Groups'].map(v=>pill(v,u.filter||'All')).join('')}</div><div class="sim-scroll">${B('filter','Archived','archive','data-value="Archived"','sim-archived')}${list.map(t=>{const c=m.contact(t.members[0]),last=d.messages.filter(x=>x.thread===t.id&&!x.deleted).at(-1);return `<button type="button" class="sim-chat-row" data-sim-action="chat" data-id="${t.id}">${t.group?`<span class="sim-avatar sim-group-avatar">${icon('people')}</span>`:avatar(c)}<div><strong>${esc(t.name)}</strong><p>${last?.from==='jamie'?'✓✓ ':''}${esc(last?.attachment?'Photo or document':last?.text||'Start a conversation')}</p></div><aside><small>${last?.at||'10:15'}</small>${t.unread?`<i class="sim-badge">${t.unread}</i>`:''}</aside></button>`;}).join('')||empty('No conversations match this filter.')}</div>${B('new-chat','', 'plus','aria-label="New chat"','sim-fab')} ${nav([['Chats','mail'],['Updates','clock'],['Communities','people'],['Calls','call']],u.tab||'Chats')}`;
  }
  function gmail({m,u}){
    const d=m.data;
    if(u.page==='compose'){const draft=d.drafts.find(x=>x.id===u.draft);if(!draft)return empty('Your draft has been sent.');return `<form class="sim-mail-compose" data-sim-form="mail">${toolbar('',ib('attach','Attach files','attach')+'<button type="submit" class="sim-icon-button" aria-label="Send email">'+icon('send')+'</button>'+ib('compose-menu','Compose options','more'),true)}<div class="sim-compose-field"><span>From</span><strong>jamie@example.test</strong></div><label class="sim-compose-field"><span>To</span><input aria-label="To" data-sim-input="mail-to" value="${esc(m.contact(draft.to)?.email||draft.to)}" placeholder="Recipient" maxlength="160"></label>${draft.cc!==undefined?`<label class="sim-compose-field"><span>Cc</span><input aria-label="Cc" data-sim-input="mail-cc" value="${esc(draft.cc)}"></label><label class="sim-compose-field"><span>Bcc</span><input aria-label="Bcc" data-sim-input="mail-bcc" value="${esc(draft.bcc)}"></label>`:''}<div class="sim-recipient-suggestions"><small>Suggestions</small><div>${d.contacts.slice(0,3).map(c=>`<button type="button" data-sim-action="recipient" data-id="${c.id}">${avatar(c)}<span>${c.name}</span></button>`).join('')}</div></div><label class="sim-compose-subject"><input aria-label="Subject" placeholder="Subject" data-sim-input="mail-subject" value="${esc(draft.subject)}" maxlength="160"></label><textarea aria-label="Compose email" placeholder="Compose email" data-sim-input="mail-text" maxlength="10000">${esc(draft.text)}</textarea><div class="sim-compose-attachments">${draft.attachments.map(id=>`<span>${B('preview',m.file(id)?.name,'file',attrs('id',id))}${ib('remove-mail-attachment','Remove attachment','close',attrs('id',id))}</span>`).join('')}</div><small class="sim-saved">Draft saved · Demo</small></form>`;}
    if(u.thread){const items=d.mail.filter(x=>x.thread===u.thread);items.forEach(x=>x.read=true);d.notifications.filter(n=>n.app==='gmail'&&n.target?.thread===u.thread).forEach(n=>n.read=true);return toolbar('',ib('mail-archive','Archive','archive')+ib('mail-delete','Delete','trash')+ib('mail-unread','Mark unread','mail')+ib('mail-star','Star thread','star'),true)+`<div class="sim-scroll sim-mail-thread"><h2>${esc(items[0]?.subject)}</h2>${items.map(x=>`<article>${avatar(m.contact(x.from))}<div class="sim-mail-author"><strong>${esc(m.contact(x.from)?.name)}</strong><small>${x.at} · to ${esc(m.contact(x.to)?.name||'Jamie')}</small></div><p>${esc(x.text)}</p>${x.invite?`<div class="sim-invite"><strong>Weekly planning</strong><p>Tuesday, October 6 · 10:00</p>${B('accept-invite',d.events[0].accepted?'Accepted · Open calendar':'Accept invitation','calendar')}</div>`:''}<div class="sim-mail-files">${x.attachments.map(id=>attachment(m,id)+B('save-file','Download','download',attrs('id',id))).join('')}</div></article>`).join('')}${B('mail-reply','Reply','reply')}${B('mail-reply-all','Reply all','reply')}${items.some(x=>x.folder==='trash')?B('mail-restore','Restore thread','undo'):''}${B('mail-forward','Forward','forward')}</div>`;}
    const folder=u.folder||'inbox';let items=d.mail.filter(x=>folder==='starred'?x.star:folder==='all'?x.folder!=='trash':x.folder===folder).filter(x=>!u.query||`${x.subject} ${x.text} ${m.contact(x.from)?.name}`.toLowerCase().includes(u.query.toLowerCase()));const threads=[...new Set(items.map(x=>x.thread))].sort((a,b)=>d.mail.findLastIndex(x=>x.thread===b)-d.mail.findLastIndex(x=>x.thread===a));
    return top('gmail','Search in mail',u.query)+`<div class="sim-list-label">${folder[0].toUpperCase()+folder.slice(1)}</div><div class="sim-scroll sim-inbox">${folder==='drafts'?d.drafts.map(x=>`<div class="sim-mail-row">${avatar(m.contact(x.to)||m.contact('jamie'))}${B('open-draft',x.subject||'(No subject)','',attrs('id',x.id))}<small>Draft</small></div>`).join(''):threads.map(id=>{const x=items.filter(x=>x.thread===id).at(-1),c=m.contact(x.from);return `<div class="sim-mail-row ${!x.read?'unread':''}">${avatar(c)}<button type="button" class="sim-mail-open" data-sim-action="mail-thread" data-id="${id}"><div><strong>${esc(c?.name)}</strong><time>${x.at}</time></div><b>${esc(x.subject)}</b><p>${esc(x.text.replace(/\n/g,' '))}</p></button>${ib('mail-star-one','Star conversation','star',attrs('id',id))}</div>`;}).join('')||empty('No messages here yet.')}</div>${B('compose','Compose','file','','sim-compose-fab')}${nav([['Mail','mail'],['Meet','video']],u.tab||'Mail')}`;
  }
  function fileRows({m,u,key},where,folder=null){
    let list=m.localFiles(where,folder).filter(f=>!u.category||(u.category==='Documents'?['pdf','text','slides','sheet'].includes(f.type):f.type===({Images:'image',Videos:'video',Audio:'audio',Downloads:null}[u.category]||f.type))).filter(f=>!u.query||f.name.toLowerCase().includes(u.query.toLowerCase()));if(u.tab==='Starred')list=list.filter(f=>f.favorite);if(u.tab==='Shared')list=list.filter(f=>['Shared photos','Team project'].includes(f.folder));if(u.deleted)list=m.data.copies.filter(c=>c.where===where&&c.deleted).map(c=>({...m.file(c.file),...c}));list.sort((a,b)=>(u.sort==='Modified'?(a.modified||'10:12').localeCompare(b.modified||'10:12'):a.name.localeCompare(b.name))*(u.desc?-1:1));
    return `<div class="sim-sort-row">${B('sort-options',u.sort||'Name','sort')}${B('view','',u.grid?'grid':'list','aria-label="Toggle list or grid view"')} ${u.selected?.length?B('selected-files',`${u.selected.length} selected`,'check'):''}</div><div class="sim-scroll sim-files-list ${u.grid?'grid':''}">${list.map(f=>`<div class="sim-file-row ${u.selected?.includes(f.id)?'selected':''}"><input type="checkbox" data-sim-input="file-select" data-id="${f.id}" aria-label="Select ${esc(f.name)}" ${u.selected?.includes(f.id)?'checked':''}><button type="button" draggable="${key==='pc'}" data-sim-action="preview" data-id="${f.file||f.id}">${fileIcon(f)}<span>${esc(f.name)}<small>${f.type.toUpperCase()} · ${f.size>=1?f.size.toFixed(1)+' MB':Math.round(f.size*1000)+' KB'}</small></span></button>${ib('file-menu',`Options for ${f.name}`,'more',attrs('id',f.id))}</div>`).join('')||empty('No files in this view.')}</div>`;
  }
  function files(ctx){const {m,u,key}=ctx;if(u.page==='home'&&!u.folder&&!u.category&&!u.deleted){const recent=m.localFiles(key).slice(-5);return top('files','Search files',u.query)+`<div class="sim-scroll sim-files-home"><div class="sim-section-label"><h3>Recents</h3>${B('all-files','See all')}</div><div class="sim-recents-rail">${recent.map(f=>`<button data-sim-action="preview" data-id="${f.file}">${fileIcon(f)}<strong>${esc(f.name)}</strong></button>`).join('')}</div><h3>Categories</h3><div class="sim-category-grid">${[['Downloads','download'],['Images','image'],['Videos','video'],['Audio','volume'],['Documents','file'],['Apps','grid']].map(([name,ico])=>B('category',name,ico,attrs('value',name),'sim-category')).join('')}</div><h3>Collections</h3><div class="sim-category-grid">${B('starred-files','Starred','star','','sim-category')}${B('safe-folder','Safe folder','lock','','sim-category')}</div><h3>All storage</h3>${B('all-files','Internal storage','folder','','sim-storage-card')}<div class="sim-storage-meter"><span></span></div><small>18 GB used of 128 GB · Demo</small></div>`+nav([['Home','home'],['Starred','star'],['Files','folder']],u.tab||'Home');}
    return toolbar(u.folder||u.category||(u.deleted?'Trash':'Files'),ib('files-new','New folder','plus')+ib('file-tools','File options','more'),true)+search('Search files',u.query)+(!u.folder&&!u.category&&!u.deleted?`<div class="sim-drive-folders">${[...new Set([...m.localFiles(key).map(f=>f.folder),...(m.data.folders||[]).filter(f=>f.where===key).map(f=>f.name)])].map(v=>B('folder',v,'folder',attrs('value',v))).join('')}</div>`:'')+fileRows(ctx,key,u.folder||null)+nav([['Home','home'],['Starred','star'],['Files','folder']],u.tab||'Files');}
  function drive(ctx){const {m,u}=ctx;const all=m.localFiles('drive'),folders=[...new Set([...all.map(f=>f.folder),...(m.data.folders||[]).filter(f=>f.where==='drive').map(f=>f.name)])];return top('drive','Search in Drive',u.query)+`<div class="sim-pills">${['My Drive','Computers'].map(v=>pill(v,u.driveTab||'My Drive','drive-tab')).join('')}</div>${u.folder?toolbar(u.folder,'',true):''}${!u.folder&&!u.query&&(u.tab||'Files')==='Files'?`<div class="sim-drive-folders">${folders.map(folder=>B('folder',folder,'folder',attrs('value',folder))).join('')}</div>`:''}${u.driveTab==='Computers'?`<div class="sim-scroll"><h3>This PC</h3>${fileRows(ctx,'pc')}</div>`:fileRows(ctx,'drive',u.folder||null)}${B('drive-new','', 'plus','aria-label="New in Drive"','sim-fab')}${nav([['Home','home'],['Starred','star'],['Shared','people'],['Files','folder']],u.tab||'Files')}`;}
  function photos({m,u}){const d=m.data;let list=d.photos.filter(p=>!p.deleted&&(!u.album||p.album===u.album)&&(!u.query||p.name.toLowerCase().includes(u.query.toLowerCase()))&&(u.tab!=='Favorites'||p.favorite));if(u.photo){const p=d.photos.find(p=>p.id===u.photo);return toolbar(p.name,ib('photo-favorite',p.favorite?'Unfavorite':'Favorite','heart',attrs('id',p.id))+ib('share','Share photo','share',attrs('id',p.id))+ib('photo-info','Photo information','info',attrs('id',p.id))+ib('photo-remove','Remove photo','trash',attrs('id',p.id)),true)+`<div class="sim-photo-full sim-scroll">${image(p.id,'',p.name)}</div><div class="sim-photo-controls">${B('photo-prev','Previous','back')}${B('photo-zoom','Zoom','plus')}${B('photo-next','Next','forward')}</div>`;}
    return toolbar('Google Photos',ib('profile','Demo account','people'))+search('Search your photos',u.query)+`<div class="sim-pills">${['All','Work','Weekend','Nature'].map(v=>pill(v,u.album||'All','album')).join('')}</div><div class="sim-scroll sim-photo-grid">${list.map(p=>`<button type="button" data-sim-action="photo" data-id="${p.id}">${image(p.id,'',p.name)}${p.favorite?'<span>♥</span>':''}</button>`).join('')}</div>`+nav([['Photos','image'],['Favorites','heart'],['Collections','folder']],u.tab||'Photos');}
  function article({m,u}){const a=m.data.articles.find(a=>a.id===u.article);return toolbar('',ib('save-article',a.saved?'Unsave story':'Save story','star',attrs('id',a.id))+ib('share','Share story','share',attrs('id',a.id)),true)+`<div class="sim-scroll sim-article">${image(a.image,'',a.title)}<small>${a.publisher} · ${a.byline} · ${a.at} · Demo story</small><h1>${a.title}</h1><p class="lead">${a.summary}</p>${a.sections.map(s=>`<h3>${s.heading}</h3><p>${s.text}</p>`).join('')}${B('follow-publisher',m.data.followed.includes(a.publisher)?'Following':'Follow '+a.publisher,'plus',attrs('id',a.id))}</div>`;}
  function news(ctx){const {m,u}=ctx;if(u.article)return article(ctx);const list=m.data.articles.filter(a=>!a.hidden&&(!u.query||`${a.title} ${a.publisher}`.toLowerCase().includes(u.query.toLowerCase()))&&(!u.topic||['For you','Headlines','All'].includes(u.topic)||a.topic===u.topic)&&(u.tab!=='Following'||a.saved||m.data.followed.includes(a.publisher)));return toolbar('Google News',ib('news-search','Search news','search')+B('profile','J','','','sim-profile'))+(u.showSearch?search('Search news',u.query):'')+`<div class="sim-pills news-topics">${['For you','Headlines','World','Business','Technology','Lifestyle'].map(v=>pill(v,u.topic||'For you','topic')).join('')}</div><div class="sim-news-banner">Your daily briefing · Demo stories${ib('news-info','About these stories','info')}</div><div class="sim-scroll sim-news-feed"><h2>${u.tab==='Following'?'Following':'Top stories ›'}</h2>${list.map((a,i)=>`<article class="sim-news-card ${i===0?'hero':'compact'}"><button type="button" data-sim-action="article" data-id="${a.id}">${image(a.image,'',a.title)}<small><span class="sim-publisher-mark">${a.publisher[0]}</span>${a.publisher}</small><h3>${a.title}</h3></button><div class="sim-news-meta"><small>${a.at}</small>${ib('save-article',a.saved?'Unsave story':'Save story','star',attrs('id',a.id))}${ib('article-menu','Story options','more',attrs('id',a.id))}</div></article>`).join('')||empty('Follow a publisher or save a story to see it here.')}</div>`+nav([['Home','home'],['Following','star'],['Newsstand','list']],u.tab||'Home');}
  function google(ctx){const {m,u}=ctx;if(u.article)return article(ctx);const results=u.query?m.data.articles.filter(a=>a.title.toLowerCase().includes(u.query.toLowerCase())):[];return `<header class="sim-google-top">${ib('drawer','Google menu','menu')}${B('profile','J','','','sim-profile')}</header><div class="sim-scroll sim-discover"><div class="sim-google-wordmark">Google</div><form data-sim-form="google" class="sim-google-search">${search('Search',u.query)}${ib('voice-search','Demo voice search','mic')}${ib('lens','Google Lens demo','camera')}</form><div class="sim-google-shortcuts">${B('ai-mode','AI Mode','search')}${B('voice-search','', 'mic','aria-label="Demo voice search"')}${B('lens','', 'image','aria-label="Choose Lens image"')}</div>${u.query?`<h3>Results for “${esc(u.query)}”</h3>${results.map(a=>B('article',a.title,'',attrs('id',a.id),'sim-search-result')).join('')}${m.data.files.filter(f=>f.name.toLowerCase().includes(u.query.toLowerCase())).map(f=>B('preview',f.name,'file',attrs('id',f.id),'sim-search-result')).join('')}${m.data.contacts.filter(c=>c.name.toLowerCase().includes(u.query.toLowerCase())).map(c=>B('contact-info',c.name,'people',attrs('id',c.id),'sim-search-result')).join('')}${Object.entries(brandNames).filter(([id,name])=>name.toLowerCase().includes(u.query.toLowerCase())).map(([id,name])=>B('launch',name,'',attrs('app',id),'sim-search-result')).join('')}`:`<div class="sim-weather-rail">${B('weather','London\n18° · Partly sunny','sun')}${B('weather','Sunset today\n6:40 PM','sun')}</div>${m.data.articles.filter(a=>!a.hidden).slice(0,5).map(a=>`<article class="sim-discover-card"><button type="button" data-sim-action="article" data-id="${a.id}">${image(a.image,'',a.title)}<h3>${a.title}</h3></button><footer><small>${a.publisher} · 2h</small>${ib('like-article',a.liked?'Unlike story':'Like story','heart',attrs('id',a.id))}${ib('share','Share story','share',attrs('id',a.id))}${ib('article-menu','Story options','more',attrs('id',a.id))}</footer></article>`).join('')}`}</div>`+nav([['Home','home'],['Search','search'],['Notifications','bell'],['Activity','clock']],u.tab||'Home');}
  function sheets({m,u}){const d=m.data;if(!u.sheet){let list=d.sheets.filter(s=>!s.deleted&&(!u.sheetFolder||m.localFiles('drive',u.sheetFolder).some(f=>f.sheet===s.id))&&(!u.query||s.name.toLowerCase().includes(u.query.toLowerCase())));if(u.sheetSort==='Name')list.sort((a,b)=>a.name.localeCompare(b.name));else if(u.sheetSort==='Last modified')list.sort((a,b)=>(b.modified||0)-(a.modified||0));else list.sort((a,b)=>(b.opened||0)-(a.opened||0));if(u.desc)list.reverse();return top('sheets','Search Sheets',u.query,ib('sheet-folders','Choose folder','folder'))+`<div class="sim-sort-row">${B('sheet-sort-menu',u.sheetSort||'Date opened by me','sort')}${ib('sheet-sort','Reverse sort direction','sort')}${ib('view','List or grid view',u.grid===false?'list':'grid')}</div><div class="sim-scroll sim-sheet-cards ${u.grid===false?'list':''}">${list.map(s=>`<article><div>${logo('sheets')}${B('open-sheet',s.name,'',attrs('id',s.id))}${ib('sheet-menu',`Options for ${s.name}`,'more',attrs('id',s.id))}</div><button type="button" data-sim-action="open-sheet" data-id="${s.id}" aria-label="Open ${esc(s.name)}"><div class="sim-sheet-mini">${s.worksheets[0].cells.slice(0,7).map(row=>`<span>${row.slice(0,4).map(c=>`<i>${esc(c)}</i>`).join('')}</span>`).join('')}</div></button></article>`).join('')}</div>${B('new-sheet','', 'plus','aria-label="New spreadsheet"','sim-fab')}`;}
    const s=d.sheets.find(s=>s.id===u.sheet);const ws=s.worksheets.find(w=>w.id===u.worksheet)||s.worksheets[0];u.worksheet=ws.id;return `<header class="sim-sheet-header">${ib('back','Back to Sheets','back')}<div><strong>${esc(s.name)}</strong><small>In Drive · Saved</small></div>${ib('sheet-undo','Undo','undo')}${ib('sheet-redo','Redo','redo')}${ib('sheet-share','Share spreadsheet','people')}${ib('sheet-menu','Spreadsheet options','more',attrs('id',s.id))}</header><div class="sim-sheet-formula"><small>${esc(u.cellLabel||'A1')}</small><input aria-label="Cell value or formula" data-sim-input="formula" value="${esc(u.cellValue??ws.cells[0][0])}" placeholder="Value or =SUM(E2:E5)">${ib('commit-cell','Apply cell value','check')}</div><div class="sim-scroll sim-sheet-grid" data-scroll="grid"><table><thead><tr><th></th>${Array.from({length:8},(_,i)=>`<th>${String.fromCharCode(65+i)}</th>`).join('')}</tr></thead><tbody>${ws.cells.map((row,r)=>`<tr><th>${r+1}</th>${Array.from({length:8},(_,c)=>`<td><button type="button" class="${u.row===r&&u.col===c?'selected':''}" data-sim-action="cell" data-row="${r}" data-col="${c}" aria-label="Cell ${String.fromCharCode(65+c)}${r+1}">${esc(m.formula(ws,r,c))}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><footer class="sim-sheet-footer">${ib('worksheets','Manage worksheets','list')}${B('worksheets',ws.name+' ▾','','','sim-sheet-pill')}${B('new-worksheet','', 'plus','aria-label="Add worksheet"')}</footer>`;}
  function calendar({m,u}){const day=u.day||6,month=u.month??9;const label=new Date(2026,month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});return toolbar('Google Calendar',ib('new-event','New event','plus'))+`<div class="sim-calendar-month">${ib('month-prev','Previous month','back')}<h2>${label}</h2>${ib('month-next','Next month','forward')}</div><div class="sim-calendar-grid">${['M','T','W','T','F','S','S'].map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat((new Date(2026,month,1).getDay()+6)%7)}${Array.from({length:new Date(2026,month+1,0).getDate()},(_,n)=>B('day',String(n+1),'',attrs('value',n+1),day===n+1?'selected':'')).join('')}</div><h3 class="sim-section-heading">${label} ${day}</h3><div class="sim-scroll">${m.data.events.filter(e=>e.day===day&&(e.month??9)===month).map(e=>`<div class="sim-event">${icon('calendar')}<div><strong>${esc(e.title)}</strong><small>${e.time} · ${e.accepted?'Accepted':'Invitation'}</small></div>${ib('event-menu','Event options','more',attrs('id',e.id))}</div>`).join('')||empty('Nothing scheduled. Add an event.')}</div>`;}
  function tasks({m,u}){return toolbar('Tasks',ib('new-task','New task','plus'))+`<div class="sim-pills">${['All','To do','Completed'].map(v=>pill(v,u.filter||'All')).join('')}</div><div class="sim-scroll sim-tasks-list">${m.data.tasks.filter(t=>u.filter==='Completed'?t.done:u.filter==='To do'?!t.done:true).map(t=>`<div><input type="checkbox" aria-label="Complete ${esc(t.text)}" data-sim-input="task" data-id="${t.id}" ${t.done?'checked':''}><span class="${t.done?'done':''}">${esc(t.text)}</span>${ib('delete-task','Delete task','trash',attrs('id',t.id))}</div>`).join('')}</div><form class="sim-inline-form" data-sim-form="task"><input aria-label="New task" placeholder="Add a task" maxlength="150" name="text"><button type="submit" aria-label="Add task">${icon('plus')}</button></form>`;}
  function contacts({m,u}){return toolbar('Contacts',ib('new-contact','Add demo contact','plus'))+search('Search contacts',u.query)+`<div class="sim-scroll">${m.data.contacts.filter(c=>!u.query||c.name.toLowerCase().includes(u.query.toLowerCase())).map(c=>`<button type="button" class="sim-contact-row" data-sim-action="contact-info" data-id="${c.id}">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${esc(c.role)}</small></div></button>`).join('')}</div>`;}
  function docs({m,u}){const f=m.file(u.document);if(f)return toolbar(f.name,ib('save-document','Save document','check')+ib('share','Share document','share',attrs('id',f.id)),true)+`<div class="sim-scroll sim-doc-page"><textarea aria-label="Edit document" data-sim-input="document" maxlength="12000">${esc(f.text)}</textarea><small>Saved in this demo</small></div>`;return toolbar('Google Docs',ib('new-document','New document','plus'))+search('Search documents',u.query)+`<div class="sim-scroll sim-doc-list">${m.data.files.filter(f=>['pdf','text'].includes(f.type)&&(!u.query||f.name.toLowerCase().includes(u.query.toLowerCase()))).map(f=>B('open-document',f.name,'file',attrs('id',f.id))).join('')}</div>`;}
  function chrome(ctx){const {u,m}=ctx;if(u.article)return article(ctx);return `<form class="sim-browser-bar" data-sim-form="browser">${ib('browser-back','Back','back')}${ib('browser-forward','Forward','forward')}<input aria-label="Browser address or search" name="address" placeholder="Search or enter a demo link" value="${esc(u.address||'demo://workspace')}"><button type="submit" aria-label="Go">${icon('forward')}</button></form><div class="sim-scroll sim-browser-page"><span class="sim-eyebrow">PHONEBRIDGER · DEMO</span><h1>A little more room.</h1><p>Read a story, open a document or continue a link from your PC.</p>${m.data.articles.slice(0,4).map(a=>B('article',a.title,'',attrs('id',a.id),'sim-search-result')).join('')}${B('launch','Open Google Search','search','data-app="google"')}</div>`;}
  function youtube({m,u}){if(u.video!==undefined){const playlist=root.PhoneBridgerPlaylist||[];const list=root.PhoneBridgerVideoPlaylist||playlist;return toolbar('YouTube',ib('side-video-prev','Previous video','back')+ib('side-video-next','Next video','forward'),true)+`<div class="sim-side-video"><video playsinline preload="metadata" data-sim-video></video><div>${ib('side-play','Play or pause video','play')}${ib('side-mute','Mute or unmute','volume')}</div><input type="range" min="0" max="100" value="0" data-sim-input="side-seek" aria-label="Seek side-phone video"><strong>${u.video===0?'Relax':'Kato'}</strong><small>PhoneBridger · Demo playlist</small></div>`;}return toolbar('YouTube',ib('profile','Demo account','people'))+`<div class="sim-scroll sim-video-library">${['Relax','Kato'].map((name,i)=>`<button type="button" data-sim-action="side-video" data-value="${i}"><div>${image(i===0?'photo-lake':'photo-forest','',name)}${icon('play')}</div><strong>${name}</strong><small>3:00 · PhoneBridger</small></button>`).join('')}</div>`;}
  function phonebridger({m,u,key}){const s=m.data.settings[key]||m.data.settings.left;const menu=u.pbPage||'home';const toggle=(setting,label)=>`<label class="sim-setting"><span>${label}</span><input type="checkbox" data-sim-input="setting" data-setting="${setting}" aria-label="${label}" ${s[setting]?'checked':''}></label>`;const range=(setting,label,min,max)=>`<label class="sim-range-label"><span>${label}</span><output>${s[setting]}%</output><input type="range" min="${min}" max="${max}" value="${s[setting]}" data-sim-input="setting" data-setting="${setting}" aria-label="${label}"></label>`;
    let body;if(menu==='home')body=`<div class="sim-pb-connected">${logo('phonebridger')}<h2>${s.connected?'Connected':'Disconnected'}</h2><p>Jamie’s PC · ${key==='left'?'Left':'Right'} phone</p><span>Automatic · USB / Wi-Fi</span><img class="sim-pb-devices" src="assets/app-ui-v1/devices-group-v1.png" alt="PC with connected phones"></div><div class="sim-pb-cards">${[['connection','wifi','Connection'],['mouse','keyboard','Mouse & keyboard'],['audio','volume','Audio'],['files','folder','Files'],['help','info','Help & about']].map(([id,ico,label])=>B('pb-page',label,ico,attrs('value',id))).join('')}</div>`;
    if(menu==='connection')body=`<h2>Connection</h2><div class="sim-pb-card"><strong>Jamie’s PC</strong><p>${s.connected?'Connected automatically':'Ready to reconnect'}</p>${B('pb-connect',s.connected?'Disconnect':'Reconnect','wifi')}</div><div class="sim-pb-card"><h3>Automatic connection</h3><p>USB takes priority. Wi-Fi keeps you connected when the cable is unplugged.</p>${B('pb-transport','Try USB / Wi-Fi','usb')}</div>`;
    if(menu==='mouse')body=`<h2>Mouse & keyboard</h2><div class="sim-pb-card">${toggle('keyboard','Use PC keyboard')}${range('speed','Pointer speed preview',10,400)}<div class="sim-pills">${['Small','Default','Large'].map(v=>B('pb-cursor-size',v,'',attrs('value',v),s.cursor===v?'selected':'')).join('')}</div>${B('pb-test','Test transition','monitor')}<p>These controls preview the app UI. Demo mouse movement stays the same.</p><input placeholder="Try typing here" aria-label="Keyboard preview" data-sim-input="keyboard-preview" value="${esc(u.keyboardText||'')}"></div>`;
    if(menu==='audio')body=`<h2>Audio</h2><div class="sim-pb-card">${toggle('audio','Audio to PC')}${range('volume','Volume',0,100)}${toggle('mute','Mute phone media')}${B('pb-audio-preview','Play / pause audio preview','play')}<div class="sim-audio-bars ${s.audio?'active':''}">${'<i></i>'.repeat(12)}</div><p>${s.audio?'Demo audio routing enabled':'Enable audio to preview routing'}</p></div>`;
    if(menu==='files')body=`<h2>Files</h2><div class="sim-pb-card"><label>Receiving folder<select aria-label="Receiving folder" data-sim-input="setting" data-setting="destination">${['Downloads','Documents','Images'].map(v=>`<option ${v===s.destination?'selected':''}>${v}</option>`).join('')}</select></label>${toggle('overwrite','Ask before overwrite')}${toggle('openFolder','Open folder after transfer')}${B('send-pc','Send files to PC','upload')}${B('launch','Open Files','folder','data-app="files"')}</div><h3>Recent transfers</h3>${transferList(m)}`;
    if(menu==='help')body=`<h2>A little help</h2><div class="sim-pb-card"><p>Move your mouse through a screen edge. Your keyboard follows the selected field.</p><p>Use Back, Home and Recents to move between apps.</p><p>Press Escape to leave mouse control. The mouse wheel scrolls the website.</p><strong>PhoneBridger · Demo UI concept</strong><p>This menu previews the companion experience.</p>${B('quiet',m.data.quiet?'Resume demo activity':'Pause demo activity','pause')}</div>`;
    return toolbar('PhoneBridger',logo('phonebridger'),menu!=='home')+`<div class="sim-scroll sim-pb-mobile">${body}</div>`;}
  function transferList(m){return `<div class="sim-transfer-list">${m.data.transfers.slice().reverse().map(t=>`<div class="sim-transfer"><strong>${t.files.map(id=>m.file(id)?.name).join(', ')}</strong><small>${t.from} → ${t.to} / ${esc(t.folder)} · ${t.status}</small><progress max="100" value="${t.progress}"></progress>${['running','queued','paused','conflict'].includes(t.status)?`<div>${B(t.status==='paused'?'transfer-resume':'transfer-pause',t.status==='paused'?'Resume':'Pause','',attrs('id',t.id))}${B('transfer-cancel','Cancel','',attrs('id',t.id))}${t.status==='conflict'?B('transfer-conflict','Resolve conflict','',attrs('id',t.id)):''}</div>`:''}</div>`).join('')||'<p>No transfers yet.</p>'}</div>`;}
  function preview({m,u}){const f=m.file(u.preview);if(!f)return empty('File not found.');let content=f.type==='image'?image(f.photo,'sim-preview-image',f.name):f.type==='sheet'?`<p>Open this document in Sheets to edit its cells.</p>${B('open-sheet','Open in Sheets','',attrs('id',f.sheet))}`:f.type==='zip'?`<h3>Archive contents</h3>${f.contents.map(id=>B('preview',m.file(id)?.name,'file',attrs('id',id))).join('')}`:f.type==='video'?`<p>Open this clip in the side-phone video library.</p>${B('side-video','Open video','play',attrs('value',f.video))}`:f.type==='slides'?`<div class="sim-slide-preview"><h2>${esc(f.slides[u.slide||0])}</h2><p>${esc((f.text||'').split('\n\n')[1])}</p>${B('slide-next','Next slide','forward')}</div>`:`<div class="sim-document-preview">${esc(f.text)}</div>`;return toolbar(f.name,ib('save-file','Save to this device','download',attrs('id',f.id))+ib('share','Share file','share',attrs('id',f.id)),true)+`<div class="sim-scroll sim-preview">${content}</div>`;}
  function pcGmail(ctx){const {m,u}=ctx;const folder=u.folder||'inbox';const original=gmail(ctx);const body=u.page==='compose'||u.thread?original:original.replace(/^<header[\s\S]*?<\/header>/,'');return `<header class="sim-pc-gmail-header">${ib('drawer','Mail navigation','menu')}${logo('gmail')}<strong>Gmail</strong>${search('Search in mail',u.query)}${ib('profile','Demo account','settings')}${avatar(m.contact('jamie'))}</header><div class="sim-pc-gmail-layout"><aside>${B('compose','Compose','file')}${['inbox','starred','sent','drafts','archive','trash'].map(v=>B('mail-folder',v[0].toUpperCase()+v.slice(1),v==='starred'?'star':v==='trash'?'trash':'mail',`data-value="${v}"`,folder===v?'selected':'')).join('')}<small>Labels</small><span>◇ Team project</span></aside><div class="sim-pc-gmail-body">${!u.thread&&u.page!=='compose'?'<div class="sim-pc-gmail-categories"><strong>▣ Primary</strong><span>♧ Promotions</span><span>♧ Social</span></div>':''}${body}</div></div>`;}
  function pcFiles(ctx){const {u}=ctx;return `<div class="sim-explorer-command">${ib('back','Back in File Explorer','back')}${B('files-new','New','plus')}${B('file-tools','File actions','more')}${B('transfers','Transfers','download')}</div><div class="sim-explorer-address">${icon('folder')}<strong>This PC</strong><span>› ${esc(u.folder||'All files')}</span>${search('Search files',u.query)}</div><div class="sim-explorer-layout"><aside>${B('all-files','Home','home')}${['Downloads','Pictures','Documents'].map(v=>B('folder',v,'folder',attrs('value',v),u.folder===v?'selected':'')).join('')}${B('starred-files','Favorites','star')}${B('deleted-files','Recycle Bin','trash')}<hr><small>This PC</small><span>Local Disk (C:)</span></aside><main>${fileRows(ctx,'pc',u.folder||null)}</main></div><footer class="sim-explorer-status">This PC · Demo files<span>${u.selected?.length||0} selected</span></footer>`;}
  function render(ctx){if(ctx.u.app==='creators')return root.PhoneBridgerCreators.render(ctx);if(ctx.u.preview)return preview(ctx);if(ctx.key==='pc'&&ctx.u.app==='gmail')return pcGmail(ctx);if(ctx.key==='pc'&&ctx.u.app==='files')return pcFiles(ctx);return ({home,whatsapp,gmail,files,drive,photos,news,google,sheets,calendar,tasks,contacts,docs,chrome,youtube,phonebridger}[ctx.u.app]||home)(ctx);}
  root.PhoneBridgerApps={render,transferList,fileRows};
})(window);
